import pytest

from sales_dashboard.loader import (
    daily_conversion_counts,
    dedupe_sessions,
    parse_session_log,
)
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def session(id_, day, converted):
    return {"id": id_, "day": day, "converted": converted}


def test_conversion_rate_none_counts_as_not_converted():
    events = [session("a", 1, True), session("b", 1, None), session("c", 1, False)]
    assert conversion_rate(events) == pytest.approx(1 / 3)
    assert conversion_rate([session("a", 1, None)]) == 0.0


def test_conversion_rate_empty():
    result = conversion_rate([])
    assert result == 0.0
    assert isinstance(result, float)


def test_pooled_conversion_rate_weights_sessions_not_groups():
    groups = {
        "small": [session("a", 1, True)],
        "large": [session("b", 1, False), session("c", 1, None), session("d", 1, False)],
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == 0.25


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_pooled_conversion_rate_no_sessions(groups):
    assert pooled_conversion_rate(groups) == 0.0


@pytest.mark.parametrize(
    "counts, days, expected",
    [([1, 2, 4], 0, 0), ([1, 2, 4], 1, 4), ([1, 2, 4], 2, 6),
     ([1, 2, 4], 3, 7), ([1, 2, 4], 10, 7), ([], 2, 0)],
)
def test_conversions_in_window(counts, days, expected):
    assert conversions_in_window(counts, days) == expected


def test_parse_session_log_flags_and_field_whitespace():
    events = parse_session_log([" a , 1 , 1 \n", " b , -2 , 0 ", " c , 3 , \t"])
    assert events == [session("a", 1, True), session("b", -2, False), session("c", 3, None)]
    assert events[0]["converted"] is True
    assert events[1]["converted"] is False
    assert events[2]["converted"] is None


def test_parse_session_log_skips_blank_and_comment_lines():
    lines = ["", " \t\n", "#comment", " \t# comment,not,a,session", "a,1,1", "b#id,2,0"]
    assert parse_session_log(lines) == [session("a", 1, True), session("b#id", 2, False)]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,1,extra", "a,not-a-day,1", "a,1.5,0", "a,,1"])
def test_parse_session_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 4\b"):
        parse_session_log(["# comment", " \t", "valid,1,1", bad_line])


def test_dedupe_sessions_keeps_last_duplicate_id_and_sorts():
    events = [
        session("a", 9, True),
        session("c", 2, True),
        session("b", 1, False),
        session("a", 2, None),
        session("c", 2, False),
    ]
    assert dedupe_sessions(events) == [events[2], events[3], events[4]]
    assert dedupe_sessions([]) == []


def test_daily_conversion_counts_inclusive_filled_and_filtered():
    events = [
        session("before", 0, True), session("after", 5, True),
        session("a", 1, True), session("b", 1, True),
        session("c", 2, False), session("d", 2, None), session("e", 4, True),
    ]
    assert daily_conversion_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_conversion_counts(events, 1, 1) == [2]
    assert daily_conversion_counts(events, 4, 1) == []
    assert daily_conversion_counts([], -1, 1) == [0, 0, 0]


def test_campaign_summary_pools_rounds_and_uses_calendar_days():
    groups = {
        "a": [session("a", 1, True)],
        "b": [session("b", 4, True), session("c", 6, None)],
        "empty": [],
    }
    assert campaign_summary(groups, 2) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert campaign_summary(groups, 3) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert campaign_summary(groups, 20) == {"rate": 0.667, "recent": 2, "groups": 2}
    assert campaign_summary(groups, 0)["recent"] == 0


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_campaign_summary_no_sessions(groups):
    assert campaign_summary(groups, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_converting_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "empty": [],
        "z": [session("z", 1, True)],
        "low": [session("low", 1, False)],
        "a": [session("a", 1, True)],
    }
    assert top_converting_groups(groups, 2) == ["a", "z"]
    assert top_converting_groups(groups, 10) == ["a", "z", "low"]
    assert top_converting_groups(groups, 0) == []
    assert top_converting_groups({}, 2) == []


def test_conversion_rate_by_group_sorted_keys_and_empty_none():
    groups = {"z": [], "b": [session("b", 1, None)], "a": [session("a", 1, True)]}
    result = conversion_rate_by_group(groups)
    assert result == {"a": 1.0, "b": 0.0, "z": None}
    assert list(result) == ["a", "b", "z"]
    assert conversion_rate_by_group({}) == {}


@pytest.mark.parametrize(
    "counts, expected",
    [([], 0), ([0, -1, 0], 0), ([1, 2, 0, 3], 2),
     ([1, -1, 2, 3, 4, 0, 5], 3), ([1, 2, 3], 3)],
)
def test_longest_conversion_streak(counts, expected):
    assert longest_conversion_streak(counts) == expected
